export const ROLES = {
  /** Майстер і вище (операції зі статусом/смігом заявок). */
  TECH: ["ADMIN", "MANAGER", "TECHNICIAN"],
  /** Менеджер і вище (довідники, фінанси). */
  MANAGER: ["ADMIN", "MANAGER"],
} as const;
